import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {useCallback, useEffect, useMemo} from 'react'
import {useNavigate} from 'react-router'

import {useHash} from '../../../hooks/routes'
import {useProjectData} from '../../../hooks/useEntity'
import {usePermission} from '../../../hooks/usePermission'
import {getSingleProjectArg} from '../../../rest/projects'
import {restApi} from '../../../services/rest'
import type {ProjectId} from '../../../types'
import {Permission} from '../../../types'

import {generateRecipeHash, parseRecipeHash} from './RecipesOverview.utils'
import type {PublicRecipesSettingsResponse} from './RecipesOverviewPage.rest'
import {PublicRecipesMode, recipesOverviewApi, RecipeType} from './RecipesOverviewPage.rest'

export const useRecipesOverviewPageNavigation = () => {
  const hash = useHash()
  const navigate = useNavigate()

  const navigateToRecipeEntity = useCallback(
    (
      recipeId?: string,
      recipeType: RecipeType = RecipeType.PRIVATE_RECIPE,
      projectId: ProjectId = '' as ProjectId,
    ) => {
      let newHashURL = ''

      if (recipeId && recipeType && projectId) {
        newHashURL = generateRecipeHash(recipeId, recipeType, projectId)
      }

      navigate({
        pathname: document.location.pathname,
        search: document.location.search,
        hash: newHashURL,
      })
    },
    [navigate],
  )

  const navigationData = useMemo(() => parseRecipeHash(hash), [hash])

  return {
    navigateToRecipeEntity,
    navigationData,
  }
}

export const useRecipeOverviewData = (projectId: ProjectId) => {
  const projectData = restApi.endpoints.getProjectNormalized.useQuery(
    getSingleProjectArg(projectId, {
      withBuildTypes: false,
      withLinks: false,
      withParameters: false,
      withDescription: false,
      withPauseComment: false,
      withPipelines: false,
    }),
  )
  const settingsData = recipesOverviewApi.endpoints.getPublicRecipesSettings.useQuery({
    projectId,
  })
  const project = useProjectData({projectId}, project => project)

  useEffect(() => {
    if (projectData.isError) {
      alertService.error('Could not load project data')
    }

    if (settingsData.isError) {
      alertService.error('Could not load public recipes settings')
    }
  }, [projectData.isError, settingsData.isError])

  return {
    isLoading: projectData.isLoading || settingsData.isLoading,
    isError: projectData.isError || settingsData.isError,
    settings: settingsData.data ?? null,
    project,
  }
}

export const useRecipeSettingsProps = (
  projectId: ProjectId,
  settings?: PublicRecipesSettingsResponse | null,
) => {
  const project = useProjectData({projectId}, project => project)
  const [requestToggleRecipesEditing] =
    recipesOverviewApi.endpoints.togglePublicRecipesEditing.useMutation()
  const canEditProject = usePermission(Permission.EDIT_PROJECT, projectId)

  const onModeChange = useCallback(
    async (mode: PublicRecipesMode) => {
      try {
        await requestToggleRecipesEditing({
          mode,
          projectId,
        })

        alertService.message(
          `Public recipes ${mode === PublicRecipesMode.ENABLED ? 'enabled' : 'disabled'}`,
        )
      } catch (e) {
        alertService.error(`Could not toggle public recipes editing: ${(e as Error).message}`)
      }
    },
    [projectId, requestToggleRecipesEditing],
  )

  const isReadOnly = project?.readOnlyUI?.value === true
  const enabled = settings?.publicRecipesMode === PublicRecipesMode.ENABLED
  const editable = canEditProject && !isReadOnly && !settings?.publicRecipesSettingsEditingDisabled
  const prohibitedByProject =
    !project?.readOnlyUI && canEditProject && settings?.publicRecipesSettingsEditingDisabled
      ? (settings?.publicRecipesInheritedModeProjectExternalId as ProjectId)
      : undefined

  return {
    enabled,
    editable,
    prohibitedByProject,
    onModeChange,

    canEditProject,
    readOnlyUI: isReadOnly,
    publicRecipesSettingsEdittingDisabled: settings?.publicRecipesSettingsEditingDisabled ?? false,
  }
}
