import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import {useCallback, useState} from 'react'

import type {ProjectId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import type {RecipeType, RecipeUsageDto} from '../RecipesOverviewPage.rest'
import {recipesOverviewApi} from '../RecipesOverviewPage.rest'
import {groupRecipeUsagesByType} from '../RecipeUsages/RecipeUsages.utils'

type RecipeViewData = {
  recipeId: string
  recipeType: RecipeType
  projectId: ProjectId
}
export const useRecipeViewData = ({recipeId, recipeType, projectId}: RecipeViewData) => {
  const {data, isLoading, isSuccess} = recipesOverviewApi.endpoints.getOneRecipeOverview.useQuery({
    recipeId,
    recipeType,
    projectId,
  })

  const [error, setError] = useState<string | null>(null)
  const resetError = useCallback(() => setError(null), [setError])
  const usages = groupRecipeUsagesByType(data?.usages ?? (emptyArray as Array<RecipeUsageDto>))
  const [updateRecipe] = recipesOverviewApi.endpoints.updatePrivateRecipe.useMutation()
  const updateRecipeHandler = useCallback(
    async (content: string) => {
      setError(null)
      try {
        await updateRecipe({
          recipeId,
          projectId,
          content,
        }).unwrap()
        window.location.reload()
      } catch (err) {
        // @ts-expect-error non-specified err type
        const errortext = err?.data ?? 'Undefined error'
        setError(errortext)
        alertService.error(`Failed to update recipe: ${errortext}`)
      }
    },
    [projectId, recipeId, updateRecipe],
  )

  return {
    data,
    isLoading,
    isSuccess,
    usages,
    updateRecipe: updateRecipeHandler,
    error,
    resetError,
  }
}
