import {LanguageSupport} from '@codemirror/language'
import {indentationMarkers} from '@replit/codemirror-indentation-markers'

import {xmlLanguage} from '@codemirror/lang-xml'
import type {ViewUpdate} from '@codemirror/view'
import {useCodeMirror} from '@uiw/react-codemirror'
import type {UseCodeMirror} from '@uiw/react-codemirror'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import useYamlEditorTheme from '../../../../pages/PipelinesPages/EditPipelinePage/EditPipelineYAML/YamlEditor/hooks/useYamlEditorTheme'
import yamlLanguage from '../../../../pages/PipelinesPages/EditPipelinePage/EditPipelineYAML/YamlEditor/utils/yamlLangParser'

const isTestEnv = process.env.NODE_ENV === 'test'

function useRecipeEditor(
  value: string,
  onChange?: (value: string) => void,
  readOnly = true,
  isXML = false,
) {
  const yamlEditorRef = useRef(null)
  const yamlEditorTheme = useYamlEditorTheme()
  const [currentYaml, setCurrentYaml] = useState<string>(value)
  const codeMirrorChangeHandler = useCallback(
    (valueYaml: string, viewUpdate: ViewUpdate) => {
      if (viewUpdate.docChanged) {
        setCurrentYaml(valueYaml)
        if (onChange) {
          onChange(valueYaml)
        }
      }
    },
    [onChange],
  )
  const yamlEditorSettings: UseCodeMirror = useMemo(
    () => ({
      /**
       * Due to a problem related to rendering the codemirror
       * in the jest snapshot tests
       */
      container: !isTestEnv ? yamlEditorRef.current : null,
      theme: yamlEditorTheme,
      onChange: codeMirrorChangeHandler,
      autoFocus: true,
      basicSetup: {
        foldGutter: false,
        autocompletion: true,
        lineNumbers: true,
        lintKeymap: true,
      },
      value,
      editable: !readOnly,
      readOnly,
      extensions: [
        isXML ? new LanguageSupport(xmlLanguage) : new LanguageSupport(yamlLanguage),
        indentationMarkers(),
      ],
    }),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [yamlEditorRef.current, yamlEditorTheme, value],
  )
  const {view, setContainer} = useCodeMirror(yamlEditorSettings)
  useEffect(() => {
    if (yamlEditorRef.current && process.env.NODE_ENV !== 'test') {
      setContainer(yamlEditorRef.current)
    }
  }, [setContainer])

  useEffect(() => {
    view?.contentDOM.setAttribute('data-enable-grammarly', 'false')
    view?.contentDOM.setAttribute('aria-label', 'Recipes Content')
  }, [view])

  return {
    yamlEditorRef,
    currentYaml,
  }
}

export default useRecipeEditor
