import {useCallback, useMemo, useState} from 'react'

import {emptyArray} from '../../../../utils/empty'
import type {RecipeDto} from '../RecipesOverviewPage.rest'
import {RecipeType} from '../RecipesOverviewPage.rest'

export enum RecipeTypeFilter {
  ALL = 'ALL',
  PUBLIC = RecipeType.PUBLIC_RECIPE,
  PRIVATE = RecipeType.PRIVATE_RECIPE,
}

export const useRecipeFilters = (recipes: Array<RecipeDto> = emptyArray as Array<RecipeDto>) => {
  const [recipeNameFilter, setRecipeNameFilter] = useState<string>('')
  const [recipeTypeFilter, setRecipeTypeFilter] = useState<RecipeTypeFilter>(RecipeTypeFilter.ALL)

  const setNameFilter = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setRecipeNameFilter(e.target.value)
  }, [])
  const setTypeFilter = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
    const target = e.target as HTMLButtonElement
    const filterType = target.dataset.typeFilter as RecipeTypeFilter
    setRecipeTypeFilter(filterType)
  }, [])

  const filteredByTypeRecipes = useMemo(() => {
    if (recipeTypeFilter === RecipeTypeFilter.ALL) {
      return recipes ?? []
    }

    return recipes.filter(i => i.type.toLowerCase() === recipeTypeFilter.toLowerCase()) ?? []
  }, [recipes, recipeTypeFilter])

  const filteredRecipes = useMemo(
    () =>
      filteredByTypeRecipes.filter(i => {
        if (i.title.toLowerCase().includes(recipeNameFilter.toLowerCase())) {
          return true
        }

        return i.id.toString().toLowerCase().includes(recipeNameFilter.toLowerCase())
      }),
    [filteredByTypeRecipes, recipeNameFilter],
  )

  return {
    recipeTypeFilter,
    recipeNameFilter,
    setNameFilter,
    setTypeFilter,
    filteredRecipes,
  }
}
