import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import Upload from '@jetbrains/ring-ui-built/components/upload/upload'
import type {FormEvent, ChangeEvent} from 'react'
import {useCallback, useState} from 'react'

import type {ProjectId} from '../../../../types'
import {recipesOverviewApi} from '../RecipesOverviewPage.rest'

import styles from './RecipeUploadDialog.module.css'

interface OwnProps {
  onClose: () => void
  projectId: ProjectId
}

function RecipeUploadDialog({onClose, projectId}: OwnProps) {
  const [fileName, setFileName] = useState('')
  const [file, setFile] = useState<File | null>(null)
  const [error, setError] = useState('')

  const handleFileChange = useCallback((files: Array<File>) => {
    const selectedFile = files[0]
    setError('')

    setFile(selectedFile)
    setFileName(selectedFile.name)
  }, [])

  const handleFileNameChange = useCallback((event: ChangeEvent<HTMLInputElement>) => {
    setFileName(event.target.value)
  }, [])

  const [uploadRecipe] = recipesOverviewApi.endpoints.uploadPrivateRecipe.useMutation()

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault()

    if (!file) {
      setError('Please select a file to upload')
      return
    }

    if (!fileName.trim()) {
      setError('Please enter a file name')
      return
    }

    try {
      await uploadRecipe({file, fileName, projectId}).unwrap()

      onClose()
      window.location.reload()
    } catch (err) {
      // Handle error response
      if (err && typeof err === 'object' && 'data' in err) {
        // Display the error message from the server if available
        setError(String(err.data) || 'Failed to upload recipe')
      } else {
        setError('An error occurred while uploading the recipe')
      }
    }
  }

  return (
    <span
      role="presentation"
      onClick={(event: React.MouseEvent<HTMLElement>) => event.stopPropagation()}
    >
      <Dialog onCloseAttempt={onClose} show contentClassName={styles.dialog} showCloseButton>
        <Header>{'Upload Recipe'}</Header>
        <Content>
          <form onSubmit={handleSubmit}>
            <div className={styles.formGroup}>
              <Upload multiple={false} onFilesSelected={handleFileChange} accept={'.xml,.yml'}>
                {'Browse or drop file to upload'}
              </Upload>
            </div>
            <div className={styles.formGroup}>
              <Input
                label={'File name'}
                id="fileName"
                value={fileName}
                onChange={handleFileNameChange}
                placeholder="Enter file name"
                className={styles.fileName}
              />
              <Text className={styles.hint}>{'Only .yml and .xml files are supported'}</Text>
            </div>

            {error && <div className={styles.error}>{error}</div>}
          </form>
        </Content>
        <Panel className={styles.panel}>
          <Button
            primary
            onClick={handleSubmit}
            disabled={file == null || fileName.trim() === '' || error !== ''}
          >
            {'Upload'}
          </Button>
          <Button onClick={onClose}>{'Cancel'}</Button>
        </Panel>
      </Dialog>
    </span>
  )
}

export default RecipeUploadDialog
