import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import type {ReactNode} from 'react'
import {useCallback} from 'react'

import MiddleEllipsis from '../../../common/MiddleEllipsis/MiddleEllipsis'
import RecipeLabel from '../RecipeLabel/RecipeLabel'
import {useRecipesPermissions} from '../RecipesOverviewPage.context'
import type {RecipeDto} from '../RecipesOverviewPage.rest'
import {RecipeType} from '../RecipesOverviewPage.rest'

import styles from './RecipeList.module.css'

function RecipeListItemTitle({item}: {item: RecipeDto}) {
  const {enabled} = useRecipesPermissions()
  const Wrapper = useCallback(
    ({children}: {children: ReactNode}) => {
      if (item.type === RecipeType.PUBLIC_RECIPE && !enabled) {
        return (
          <Tooltip long title={'Public JetBrains Marketplace recipes disabled for this project'}>
            <div className={styles.recipeNameColumn}>{children}</div>
          </Tooltip>
        )
      }

      return <div className={styles.recipeNameColumn}>{children}</div>
    },
    [enabled, item.type],
  )

  return (
    <div
      className={classNames(item.type === RecipeType.PUBLIC_RECIPE && !enabled && styles.disabled)}
    >
      <Wrapper>
        <div>
          <MiddleEllipsis className={styles.recipeTitle}>{item.title}</MiddleEllipsis>
          {item.labels.map(label => (
            <RecipeLabel
              label={label}
              key={label.link}
              withTooltip={item.type === RecipeType.PUBLIC_RECIPE}
            />
          ))}
        </div>
        <MiddleEllipsis className={styles.recipeId}>{item.id.toString()}</MiddleEllipsis>
      </Wrapper>
    </div>
  )
}

export default RecipeListItemTitle
