import {useMemo} from 'react'

import type {RecipeDto} from '../RecipesOverviewPage.rest'
import {RecipeUsageType} from '../RecipesOverviewPage.rest'
import {groupRecipeUsagesByType} from '../RecipeUsages/RecipeUsages.utils'
import RecipeUsagesWrapper, {RecipeUsagesViewMode} from '../RecipeUsages/RecipeUsagesWrapper'

import styles from './RecipeList.module.css'

function RecipeListItemUsages({item}: {item: RecipeDto}) {
  const usages = useMemo(() => groupRecipeUsagesByType(item.usages), [item.usages])

  if (!item.usages || item.usages?.length === 0) {
    return <span>{'-'}</span>
  }

  return (
    <>
      <RecipeUsagesWrapper
        usages={usages.buildConfigurations}
        usageType={RecipeUsageType.BUILD_TYPE}
        viewMode={RecipeUsagesViewMode.DROPDOWN}
      />
      <RecipeUsagesWrapper
        usages={usages.buildTemplates}
        usageType={RecipeUsageType.BUILD_TYPE_TEMPLATE}
        viewMode={RecipeUsagesViewMode.DROPDOWN}
      />
      <RecipeUsagesWrapper
        usages={usages.privateRecipes}
        usageType={RecipeUsageType.PRIVATE_RECIPE}
        viewMode={RecipeUsagesViewMode.DROPDOWN}
      />
      <span className={styles.spring} />
    </>
  )
}

export default RecipeListItemUsages
