import type {RecipeUsageDto} from '../RecipesOverviewPage.rest'

import RecipeUsageItem from './RecipeUsages.item'

interface OwnProps {
  usages: Array<RecipeUsageDto>
}

function RecipeUsagesList(props: OwnProps) {
  return props.usages.map(({id, type, name, projectId}) => (
    <span key={id} role="presentation" onClick={e => e.stopPropagation()}>
      <RecipeUsageItem projectId={projectId} type={type} name={name} id={id} />
    </span>
  ))
}

export default RecipeUsagesList
