import type {RecipeUsageDto} from '../RecipesOverviewPage.rest'
import {RecipeUsageType} from '../RecipesOverviewPage.rest'

export function groupRecipeUsagesByType(usages: Array<RecipeUsageDto>) {
  return usages.reduce(
    (acc, curr) => {
      switch (curr.type) {
        case RecipeUsageType.BUILD_TYPE:
          acc.buildConfigurations.push(curr)
          break
        case RecipeUsageType.BUILD_TYPE_TEMPLATE:
          acc.buildTemplates.push(curr)
          break
        case RecipeUsageType.PRIVATE_RECIPE:
          acc.privateRecipes.push(curr)
          break
        default:
          break
      }
      return acc
    },
    {
      privateRecipes: [] as Array<RecipeUsageDto>,
      buildConfigurations: [] as Array<RecipeUsageDto>,
      buildTemplates: [] as Array<RecipeUsageDto>,
    },
  )
}
