import InfoIcon from '@jetbrains/icons/info-filled.svg'
import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import Icon from '@jetbrains/ring-ui-built/components/icon'
import {Content, Header} from '@jetbrains/ring-ui-built/components/island/island'
import Panel from '@jetbrains/ring-ui-built/components/panel/panel'
import Text from '@jetbrains/ring-ui-built/components/text/text'
import plur from 'plur'
import type React from 'react'
import {useCallback, useMemo} from 'react'

import {useRecipesOverviewPageNavigation} from '../RecipesOverviewPage.hooks'
import type {RecipeDto} from '../RecipesOverviewPage.rest'
import {recipesOverviewApi, RecipeType, RecipeUsageType} from '../RecipesOverviewPage.rest'
import {groupRecipeUsagesByType} from '../RecipeUsages/RecipeUsages.utils'
import RecipeUsagesWrapper, {RecipeUsagesViewMode} from '../RecipeUsages/RecipeUsagesWrapper'

import styles from './RecipeDeleteDialog.module.css'

interface OwnProps {
  onClose: () => void
  recipe: RecipeDto
}

function RecipeListDeleteDialog({onClose, recipe}: OwnProps) {
  const usages = groupRecipeUsagesByType(recipe.usages)

  const {navigateToRecipeEntity} = useRecipesOverviewPageNavigation()
  const [deletePrivateRecipe] = recipesOverviewApi.endpoints.deletePrivateRecipe.useMutation()

  const deletePrivateRecipeHandler = useCallback(async () => {
    try {
      await deletePrivateRecipe({
        recipeId: recipe.id.toString(),
        projectId: recipe.projectId,
      }).unwrap()
      onClose()

      navigateToRecipeEntity()
      window.location.reload()
    } catch (err) {
      alertService.error('Failed to delete recipe')
    }
  }, [deletePrivateRecipe, navigateToRecipeEntity, onClose, recipe.id, recipe.projectId])

  const privateRecipeInfo = useMemo(() => {
    if (recipe.type === RecipeType.PRIVATE_RECIPE && recipe.usages.length > 0) {
      return (
        <div className={styles.info}>
          <Icon glyph={InfoIcon} className={styles.infoIcon} />
          <Text className={styles.infoText}>
            {' Recipes used in build configurations cannot be deleted. To remove ' +
              'a\u00A0recipe, delete any build steps that use it.'}
          </Text>
        </div>
      )
    }

    if (recipe.type === RecipeType.PRIVATE_RECIPE && recipe.usages.length === 0) {
      return <Text>{'Are you sure you want to delete this recipe? '}</Text>
    }

    return null
  }, [recipe.type, recipe.usages.length])
  const publicRecipeInfo = useMemo(
    () =>
      recipe.type === RecipeType.PUBLIC_RECIPE ? (
        <Text>
          {
            'To delete public recipe you need to delete all build steps that uses these recipe. If you need to force stop using the public recipe disable integration with marketplace in project.'
          }
        </Text>
      ) : null,
    [recipe.type],
  )

  return (
    <span
      role="presentation"
      onClick={(event: React.MouseEvent<HTMLElement>) => event.stopPropagation()}
    >
      <Dialog onCloseAttempt={onClose} show contentClassName={styles.dialog} showCloseButton>
        <Header>{`Delete ${recipe.type === RecipeType.PRIVATE_RECIPE ? 'private' : 'public'} ${plur('recipe', recipe.usages.length)}`}</Header>
        <Content>
          <div>
            {privateRecipeInfo}
            {publicRecipeInfo}
          </div>
          <div className={styles.usages}>
            <RecipeUsagesWrapper
              usages={usages.buildConfigurations}
              usageType={RecipeUsageType.BUILD_TYPE}
              viewMode={RecipeUsagesViewMode.COLLAPSING_LIST}
            />
            <RecipeUsagesWrapper
              usages={usages.buildTemplates}
              usageType={RecipeUsageType.BUILD_TYPE_TEMPLATE}
              viewMode={RecipeUsagesViewMode.COLLAPSING_LIST}
            />
            <RecipeUsagesWrapper
              usages={usages.privateRecipes}
              usageType={RecipeUsageType.PRIVATE_RECIPE}
              viewMode={RecipeUsagesViewMode.COLLAPSING_LIST}
            />
          </div>
        </Content>
        <Panel>
          {recipe.type === RecipeType.PRIVATE_RECIPE && recipe.usages.length === 0 ? (
            <>
              <Button onClick={deletePrivateRecipeHandler} danger>
                {'Delete recipe'}
              </Button>
              <Button onClick={onClose}>{'Dismiss'}</Button>
            </>
          ) : (
            <span />
          )}
        </Panel>
      </Dialog>
    </span>
  )
}

export default RecipeListDeleteDialog
