import HelpIcon from '@jetbrains/icons/help.svg'
import {H3, H4} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import SimpleTable from '@jetbrains/ring-ui-built/components/table/simple-table'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {useCallback, useMemo} from 'react'

import type {ProjectId} from '../../../../types'
import {resolveHelpURL} from '../../../../utils/url'
import type {RecipeDto} from '../RecipesOverviewPage.rest'
import {recipesOverviewApi, RecipeType} from '../RecipesOverviewPage.rest'

import RecipeControls from './RecipeList.controls'
import {useRecipeFilters} from './RecipeList.hooks'
import RecipeListItemMore from './RecipeList.item.more'
import RecipeListItemTitle from './RecipeList.item.title'
import RecipeListItemUsages from './RecipeList.item.usages'

import styles from './RecipeList.module.css'

type OwnProps = {
  projectId: ProjectId
  onRecipeSelect: (recipeId: string, recipeType: RecipeType, projectId: ProjectId) => void
}

const getColumns = (projectId: ProjectId) => [
  {
    id: 'title',
    title: 'Name',
    className: styles.titleColumn,
    getValue: (item: RecipeDto) => <RecipeListItemTitle item={item} />,
  },
  {
    id: 'type',
    title: 'Type',
    getValue: (item: RecipeDto) => (item.type === RecipeType.PUBLIC_RECIPE ? 'Public' : 'Private'),
  },
  {
    id: 'usages',
    title: 'Usage',
    getValue: (item: RecipeDto) => <RecipeListItemUsages item={item} />,
  },
  {
    id: 'custom',
    title: 'Custom',
    className: styles.moreColumn,
    getHeaderValue: () => null,
    getValue: (item: RecipeDto) => <RecipeListItemMore item={item} projectId={projectId} />,
  },
]

function RecipeList({projectId, onRecipeSelect}: OwnProps) {
  const {data, isLoading} = recipesOverviewApi.endpoints.getAllRecipes.useQuery({
    projectId,
  })

  const selectRecipe = useCallback(
    (item: RecipeDto) => {
      onRecipeSelect(item.id.toString(), item.type, projectId)
    },
    [onRecipeSelect, projectId],
  )

  const {recipeTypeFilter, recipeNameFilter, setNameFilter, setTypeFilter, filteredRecipes} =
    useRecipeFilters(data?.recipes)

  const columns = useMemo(() => getColumns(projectId), [projectId])

  if (isLoading) {
    return <Loader />
  }

  return (
    <>
      <H3>{'Project Recipes'}</H3>
      <span>
        {'Recipe is a generalized build step that can be used across different configurations'}

        <Link
          aria-label="Help"
          target={'_blank'}
          rel={'noreferrer'}
          href={resolveHelpURL('working-with-meta-runner.html?Working+with+Recipes')}
        >
          <SvgIcon className={styles.helpIcon} icon={HelpIcon} />
        </Link>
      </span>
      <RecipeControls
        recipeNameFilter={recipeNameFilter}
        recipeTypeFilter={recipeTypeFilter}
        setNameFilter={setNameFilter}
        setTypeFilter={setTypeFilter}
        projectId={projectId}
      />
      <SimpleTable
        className={styles.table}
        data={filteredRecipes}
        columns={columns}
        onItemClick={selectRecipe}
        getItemClassName={() => styles.item}
        getMetaColumnClassName={() => styles.column}
        renderEmpty={() => <H4 className={styles.empty}>{'No recipes found :('}</H4>}
      />
    </>
  )
}

export default RecipeList
