import Button from '@jetbrains/ring-ui-built/components/button/button'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Radio from '@jetbrains/ring-ui-built/components/radio/radio'
import {memo, useCallback} from 'react'

import type {ProjectId} from '../../../../types'
import {useRecipesPermissions} from '../RecipesOverviewPage.context'
import type {PublicRecipesMode} from '../RecipesOverviewPage.rest'

import {useProhibitingParentProject, useSetModeLogics} from './RecipeSettings.hooks'

import styles from './RecipeSettings.module.css'

interface RecipeSettingsProps {
  prohibitedByProject?: ProjectId
  onModeChange: (mode: PublicRecipesMode) => Promise<void>
}

function RecipeSettings({prohibitedByProject, onModeChange}: RecipeSettingsProps) {
  const prohibitingData = useProhibitingParentProject(prohibitedByProject)
  const {editable, enabled} = useRecipesPermissions()
  const setModeLogics = useSetModeLogics(enabled)

  const saveMode = useCallback(() => {
    onModeChange(setModeLogics.value)
  }, [onModeChange, setModeLogics.value])

  return (
    <div>
      {prohibitedByProject ? (
        <p>
          {'The parent '}
          {prohibitingData?.editLink?.href ? (
            <Link href={prohibitingData?.editLink.href}>{prohibitingData.name}</Link>
          ) : (
            prohibitingData?.name
          )}
          {' project restricts this project from using public recipes'}
        </p>
      ) : null}

      <p className={styles.text}>{'Public JetBrains Marketplace recipes:'}</p>
      <div className={styles.radios}>
        <Radio
          value={setModeLogics.value}
          disabled={!editable}
          onChange={setModeLogics.onRadioChange}
        >
          <Radio.Item className={styles.radio} value="ENABLED">
            {'Enabled'}
          </Radio.Item>
          <Radio.Item className={styles.radio} value="DISABLED">
            {'Disabled'}
          </Radio.Item>
        </Radio>
      </div>
      <Button className={styles.save} primary disabled={!editable} onClick={saveMode}>
        {'Save'}
      </Button>
    </div>
  )
}

export default memo(RecipeSettings)
