import {createContext, useContext} from 'react'

import type {
  EditPipelineYAMLContextProps,
  EditPipelineYAMLProviderProps,
} from './EditPipelineYAMLContext.types'

const EditPipelineYAMLContext = createContext<EditPipelineYAMLContextProps>(
  {} as EditPipelineYAMLContextProps,
)

export const useEditPipelineYAMLContext = () => useContext(EditPipelineYAMLContext)

function EditPipelineYAMLContextProvider({children, value}: EditPipelineYAMLProviderProps) {
  return (
    <EditPipelineYAMLContext.Provider value={value}>{children}</EditPipelineYAMLContext.Provider>
  )
}

export default EditPipelineYAMLContextProvider
