import NewWindowIcon from '@jetbrains/icons/new-window'
import WarningIcon from '@jetbrains/icons/warning-empty.svg'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import {Fragment, useMemo} from 'react'

import type {RecipeLabel as RecipeLabelType} from '../RecipesOverviewPage.rest'
import {RecipeLabelStatus} from '../RecipesOverviewPage.rest'

import styles from './RecipeLabel.module.css'

interface OwnProps {
  label: RecipeLabelType
  withTooltip: boolean
}

const getLabelText = (label: RecipeLabelType) => {
  switch (label.status) {
    case RecipeLabelStatus.NEW_VERSION_AVAILABLE:
      return {
        text: 'New version available',
        icon: NewWindowIcon,
      }
    case RecipeLabelStatus.RECIPE_UNAVAILABLE:
      return {
        text: 'Recipe Unavailable',
        icon: WarningIcon,
        tooltip: `This recipe is not available on JetBrains Marketplace`,
      }
    case RecipeLabelStatus.VERSION_UNAVAILABLE:
      return {
        text: 'Version unavailable',
        icon: WarningIcon,
        tooltip: `This recipe version is not available on JetBrains Marketplace`,
      }
    case RecipeLabelStatus.ERROR_RETRIEVING_STATUS:
      return {
        text: 'Error retrieving status',
        icon: WarningIcon,
        tooltip:
          'Failed to retrieve recipe data: please check the connection to JetBrains Marketplace and try again later',
      }
    default:
      return {
        text: label.status,
        icon: null,
      }
  }
}

function RecipeLabel({label, withTooltip = false}: OwnProps) {
  const labelContent = useMemo(() => getLabelText(label), [label])
  const Host = label.link ? Link : Fragment
  const TooltipHost = labelContent.tooltip && withTooltip ? Tooltip : Fragment

  return (
    <div
      role="presentation"
      onClick={e => e.stopPropagation()}
      className={classNames(styles.label, {
        [styles.success]: label.status === RecipeLabelStatus.NEW_VERSION_AVAILABLE,
        [styles.warning]: [
          RecipeLabelStatus.RECIPE_UNAVAILABLE,
          RecipeLabelStatus.VERSION_UNAVAILABLE,
          RecipeLabelStatus.ERROR_RETRIEVING_STATUS,
        ].includes(label.status),
      })}
    >
      <Host className={styles.link} href={label.link} target={'_blank'} rel="noreferrer">
        <TooltipHost title={labelContent.tooltip}>
          {labelContent.icon ? <Icon glyph={labelContent.icon} className={styles.icon} /> : null}
          {labelContent.text}
        </TooltipHost>
      </Host>
    </div>
  )
}

export default RecipeLabel
