import InfoIcon from '@jetbrains/icons/info.svg'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'

import useRecipeEditor from '../../../App/BuildStepSelector/AddPublicRecipeDialog/hooks/useRecipeEditor'
import CopyIconButton from '../../../common/CopyIconButton/CopyIconButton'
import PopupMenu from '../../../common/Popup/PopupMenu'
import {RecipeType} from '../RecipesOverviewPage.rest'

import styles from './RecipeView.module.css'

interface OwnProps {
  content?: string
  editable?: boolean
  onContentChange?: (content: string) => void
  recipeType: RecipeType
}

const popupProps = {
  directions: [
    PopupMenu.PopupProps.Directions.TOP_CENTER,
    PopupMenu.PopupProps.Directions.TOP_RIGHT,
  ],
  className: styles.readonlyTooltipPopup,
}
const isXML = (content: string) => content.trim().startsWith('<')
function RecipeViewCode({content = '', editable, onContentChange, recipeType}: OwnProps) {
  const {yamlEditorRef, currentYaml} = useRecipeEditor(
    content,
    onContentChange,
    !editable,
    isXML(content),
  )

  return (
    <div className={styles.source}>
      <div className={styles.sourceHeader}>
        <div className={styles.title}>
          {`Source`}
          {(recipeType === RecipeType.PUBLIC_RECIPE && (
            <span className={styles.readonlyNote}>
              {`(view only)`}
              <Tooltip
                title={'The source code of public recipes cannot be edited'}
                long
                popupProps={popupProps}
              >
                <SvgIcon icon={InfoIcon} className={styles.infoIcon} />
              </Tooltip>
            </span>
          )) ||
            null}
        </div>
        <CopyIconButton
          title={'Copy code'}
          text={currentYaml}
          beforeCopyContent={'Copy code'}
          afterCopyContent={'Copied!'}
          wrapperClassName={styles.copy}
        />
      </div>
      <div className={styles.code} ref={yamlEditorRef} />
    </div>
  )
}

export default RecipeViewCode
