import type {ReactNode} from 'react'
import {createContext, useContext} from 'react'

interface RecipesPermissions {
  enabled: boolean
  editable: boolean

  canEditProject: boolean
  readOnlyUI: boolean
  publicRecipesSettingsEdittingDisabled: boolean
}

const RecipesPermissionsContext = createContext<RecipesPermissions>({
  editable: false,
  enabled: false,
  canEditProject: false,
  readOnlyUI: false,
  publicRecipesSettingsEdittingDisabled: false,
})

interface RecipesPermissionsProviderProps {
  children: ReactNode
  permissions: RecipesPermissions
}

export function RecipesPermissionsProvider({
  children,
  permissions,
}: RecipesPermissionsProviderProps) {
  return (
    <RecipesPermissionsContext.Provider value={permissions}>
      {children}
    </RecipesPermissionsContext.Provider>
  )
}

export function useRecipesPermissions(): RecipesPermissions {
  const context = useContext(RecipesPermissionsContext)
  if (context === undefined) {
    throw new Error('useRecipesPermissions must be used within a RecipesPermissionsProvider')
  }
  return context
}
