import Link from '@jetbrains/ring-ui-built/components/link/link'

import {getClassicOverviewHrefWithCustomBase} from '../../../../routes'
import {currentServerId} from '../../../../types/projectTrees'
import ProjectOrBuildTypeIcon from '../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon'
import {EntityIconType} from '../../../common/ProjectOrBuildTypeIcon/ProjectOrBuildTypeIcon.types'
import {generateRecipeHash} from '../RecipesOverview.utils'
import type {RecipeUsageDto} from '../RecipesOverviewPage.rest'
import {RecipeType, RecipeUsageType} from '../RecipesOverviewPage.rest'

import styles from './RecipeUsages.module.css'

type OwnProps = RecipeUsageDto

const getIconByType = (type: RecipeUsageType) => {
  switch (type) {
    case RecipeUsageType.BUILD_TYPE:
      return EntityIconType.BUILD_TYPE
    case RecipeUsageType.BUILD_TYPE_TEMPLATE:
      return EntityIconType.TEMPLATE
    default:
      return EntityIconType.PROJECT
  }
}
function RecipeUsageItem({type, name, projectId, id}: OwnProps) {
  const iconType = getIconByType(type)

  const href = new URL(
    getClassicOverviewHrefWithCustomBase({
      isAdmin: true,
      isTemplate: type === RecipeUsageType.BUILD_TYPE_TEMPLATE,
      buildTypeId: id,
      projectId: type === RecipeUsageType.PRIVATE_RECIPE ? projectId : undefined,
      serverId: currentServerId,
    }),
  )

  href.searchParams.set('tab', 'recipe')

  if (type === RecipeUsageType.PRIVATE_RECIPE) {
    href.hash = generateRecipeHash(id, RecipeType.PRIVATE_RECIPE, projectId)
  }

  return (
    <Link className={styles.link} href={href.toString()} target={'_blank'} rel="noreferrer">
      <ProjectOrBuildTypeIcon type={iconType} size={'S'} className={styles.entityIcon} />
      {name}
    </Link>
  )
}

export default RecipeUsageItem
