import type {ProjectId} from '../../../types'

import {RecipeType} from './RecipesOverviewPage.rest'

export function parseRecipeHash(hash: string) {
  const data = new URLSearchParams(hash)
  return {
    recipeId: data.get('recipeId'),
    recipeType: (data.get('recipeType') ?? RecipeType.PRIVATE_RECIPE) as RecipeType,
    projectId: data.get('projectId'),
  }
}

export function generateRecipeHash(recipeId: string, recipeType: RecipeType, projectId: ProjectId) {
  return `recipeId=${recipeId}&recipeType=${recipeType}&projectId=${projectId}`
}
