import {useCallback, useMemo, useState} from 'react'

import {useAppSelector} from '../../../../hooks/react-redux'
import {useProjectData} from '../../../../hooks/useEntity'
import {getSingleProjectArg} from '../../../../rest/projects'
import {restApi} from '../../../../services/rest'
import type {ProjectId} from '../../../../types'
import {getEditHref} from '../../../common/EditEntity/EditEntity'
import {PublicRecipesMode} from '../RecipesOverviewPage.rest'

export const useProhibitingParentProject = (projectId?: ProjectId) => {
  const {isLoading} = restApi.endpoints.getProjectNormalized.useQuery(
    getSingleProjectArg(projectId as ProjectId, {
      withBuildTypes: false,
      withLinks: true,
      withParameters: false,
      withDescription: false,
      withPauseComment: false,
      withPipelines: false,
    }),
    {skip: !projectId},
  )

  const project = useProjectData({projectId}, project => project)
  const editLink = useAppSelector(state => getEditHref(state, {projectId}))

  return useMemo(() => {
    if (!projectId) {
      return null
    }

    return {
      projectId,
      name: project?.name,
      editLink: {
        ...editLink,
        href: `${editLink.href}&tab=recipe`,
      },
      isLoading,
    }
  }, [isLoading, project?.name, projectId, editLink])
}

export const useSetModeLogics = (defaultValue: boolean) => {
  const [value, setValue] = useState<PublicRecipesMode>(
    defaultValue ? PublicRecipesMode.ENABLED : PublicRecipesMode.DISABLED,
  )

  const onRadioChange = useCallback(() => {
    setValue(settings =>
      settings === PublicRecipesMode.ENABLED
        ? PublicRecipesMode.DISABLED
        : PublicRecipesMode.ENABLED,
    )
  }, [])

  return {
    value,
    onRadioChange,
  }
}
