import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import {useMemo} from 'react'

import type {ProjectId} from '../../../types'

import RecipeList from './RecipeList/RecipeList'
import RecipeSettings from './RecipeSettings/RecipeSettings'
import {RecipesPermissionsProvider} from './RecipesOverviewPage.context'
import {
  useRecipeOverviewData,
  useRecipeSettingsProps,
  useRecipesOverviewPageNavigation,
} from './RecipesOverviewPage.hooks'
import RecipeView from './RecipeView/RecipeView'

import styles from './RecipesOverviewPage.module.css'

interface RecipeOverviewPageProps {
  projectId: ProjectId
}

function RecipesOverviewPage({projectId}: RecipeOverviewPageProps) {
  const {navigationData, navigateToRecipeEntity} = useRecipesOverviewPageNavigation()
  const recipesOverviewData = useRecipeOverviewData(projectId)
  const settingsProps = useRecipeSettingsProps(projectId, recipesOverviewData.settings)

  const permissions = useMemo(
    () => ({
      editable: settingsProps.editable,
      enabled: settingsProps.enabled,
      canEditProject: settingsProps.canEditProject,
      readOnlyUI: settingsProps.readOnlyUI,
      publicRecipesSettingsEdittingDisabled: settingsProps.publicRecipesSettingsEdittingDisabled,
    }),
    [settingsProps],
  )
  if (recipesOverviewData.isLoading) {
    return <Loader />
  }

  if (
    recipesOverviewData.isError ||
    !recipesOverviewData.settings ||
    !recipesOverviewData.project
  ) {
    return null
  }

  if (navigationData.recipeId) {
    return (
      <RecipesPermissionsProvider permissions={permissions}>
        <RecipeView
          projectId={navigationData.projectId as ProjectId}
          recipeId={navigationData.recipeId}
          recipeType={navigationData.recipeType}
          onNavigateBack={navigateToRecipeEntity}
        />
      </RecipesPermissionsProvider>
    )
  }

  return (
    <RecipesPermissionsProvider permissions={permissions}>
      <H2 className={styles.header}>{'Recipes'}</H2>
      <span className={styles.note}>
        {'This setting affects the current project as well as all of its subprojects'}
      </span>
      {!recipesOverviewData.project?.virtual &&
      recipesOverviewData.settings.arePublicRecipesAllowedAtServer ? (
        <RecipeSettings
          prohibitedByProject={settingsProps.prohibitedByProject}
          onModeChange={settingsProps.onModeChange}
        />
      ) : null}
      <RecipeList projectId={projectId} onRecipeSelect={navigateToRecipeEntity} />
    </RecipesPermissionsProvider>
  )
}

export default RecipesOverviewPage
