import searchIcon from '@jetbrains/icons/search.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import {useRef, useState} from 'react'

import {useProjectData} from '../../../../hooks/useEntity'
import type {ProjectId} from '../../../../types'
import {useRecipesPermissions} from '../RecipesOverviewPage.context'
import RecipeUploadDialog from '../RecipeUploadDialog/RecipeUploadDialog'

import {RecipeTypeFilter} from './RecipeList.hooks'

import styles from './RecipeList.module.css'

type RecipeControlsProps = {
  recipeNameFilter: string
  recipeTypeFilter: RecipeTypeFilter
  setNameFilter: (e: React.ChangeEvent<HTMLInputElement>) => void
  setTypeFilter: (e: React.MouseEvent<HTMLButtonElement>) => void
  projectId: ProjectId
}

function RecipeControls({
  recipeNameFilter,
  recipeTypeFilter,
  setNameFilter,
  setTypeFilter,
  projectId,
}: RecipeControlsProps) {
  const isVirtual = useProjectData({projectId}, project => project?.virtual)
  const inputRef = useRef<HTMLInputElement>(null)
  const [showUploadDialog, setShowUploadDialog] = useState(false)
  const {readOnlyUI, canEditProject} = useRecipesPermissions()

  return (
    <div className={styles.controls}>
      <Input
        inputRef={inputRef}
        type="search"
        placeholder={`Search by name or id`}
        icon={searchIcon}
        autoComplete={'off'}
        value={recipeNameFilter}
        onChange={setNameFilter}
      />
      <ButtonGroup className={styles.buttonGroup}>
        <Button
          onClick={setTypeFilter}
          data-type-filter={RecipeTypeFilter.ALL}
          active={recipeTypeFilter === RecipeTypeFilter.ALL}
        >
          {'All'}
        </Button>
        <Button
          onClick={setTypeFilter}
          data-type-filter={RecipeTypeFilter.PUBLIC}
          active={recipeTypeFilter === RecipeTypeFilter.PUBLIC}
        >
          {'Public'}
        </Button>
        <Button
          onClick={setTypeFilter}
          data-type-filter={RecipeTypeFilter.PRIVATE}
          active={recipeTypeFilter === RecipeTypeFilter.PRIVATE}
        >
          {'Private'}
        </Button>
      </ButtonGroup>
      {!isVirtual && !readOnlyUI && canEditProject ? (
        <Button className={styles.uploadButton} onClick={() => setShowUploadDialog(true)}>
          {'Upload private recipe'}
        </Button>
      ) : null}
      {showUploadDialog && (
        <RecipeUploadDialog onClose={() => setShowUploadDialog(false)} projectId={projectId} />
      )}
    </div>
  )
}

export default RecipeControls
