import {restBaseApi} from '../../../services/restBase'
import type {BuildTypeId, ProjectId} from '../../../types'

export enum RecipeType {
  PUBLIC_RECIPE = 'PUBLIC_RECIPE',
  PRIVATE_RECIPE = 'PRIVATE_RECIPE',
}

export enum RecipeLabelStatus {
  RECIPE_UNAVAILABLE = 'RECIPE_UNAVAILABLE',
  VERSION_UNAVAILABLE = 'VERSION_UNAVAILABLE',
  NEW_VERSION_AVAILABLE = 'NEW_VERSION_AVAILABLE',
  ERROR_RETRIEVING_STATUS = 'ERROR_RETRIEVING_STATUS',
}

export interface RecipeLabel {
  status: RecipeLabelStatus
  link?: string
}

export enum RecipeUsageType {
  BUILD_TYPE = 'BUILD_TYPE',
  BUILD_TYPE_TEMPLATE = 'BUILD_TYPE_TEMPLATE',
  PRIVATE_RECIPE = 'PRIVATE_RECIPE',
}

export interface RecipeUsageDto {
  id: BuildTypeId
  name: string
  projectId: ProjectId
  type: RecipeUsageType
}

export interface RecipeDto {
  id: string | number
  title: string
  type: RecipeType
  usages: Array<RecipeUsageDto>
  projectId: ProjectId
  editable?: boolean
  description?: string
  labels: Array<RecipeLabel>
  content?: string
  newVersionLink?: string
}

type RecipesOverviewResponse = {recipes: Array<RecipeDto>}
type RecipesOverviewResponseArgs = {
  projectId: ProjectId
}

type OneRecipeOverviewResponse = RecipeDto
type OneRecipeOverviewResponseArgs = {
  recipeId: string
  projectId: ProjectId
  recipeType: RecipeType
}

export enum PublicRecipesMode {
  ENABLED = 'ENABLED',
  DISABLED = 'DISABLED',
}

type ToggleRecipeEditingModeResponse = {
  projectId: ProjectId
  mode: PublicRecipesMode
}

interface UploadRecipeArgs {
  file: File
  fileName: string
  projectId: ProjectId
}

interface UpdateRecipeArgs {
  recipeId: string
  projectId: ProjectId
  content: string
}

export interface PublicRecipesSettingsResponse {
  arePublicRecipesAllowedAtServer: boolean
  arePublicRecipesEnabled: boolean
  publicRecipesInheritedModeProjectExternalId: string
  publicRecipesSettingsEditingDisabled: boolean
  publicRecipesInheritedModeProjectName: string
  publicRecipesMode: PublicRecipesMode
}

interface PublicRecipesSettingsResponseArgs {
  projectId: ProjectId
}

interface DeletePrivateRecipeArgs {
  recipeId: string
  projectId: ProjectId
}

export const recipesOverviewApi = restBaseApi.injectEndpoints({
  endpoints: build => ({
    getAllRecipes: build.query<RecipesOverviewResponse, RecipesOverviewResponseArgs>({
      query: params => ({
        url: `/app/recipes/overview/all`,
        method: 'GET',
        params,
      }),
    }),
    getOneRecipeOverview: build.query<OneRecipeOverviewResponse, OneRecipeOverviewResponseArgs>({
      query: params => ({
        url: `/app/recipes/overview`,
        method: 'GET',
        params,
      }),
    }),
    getPublicRecipesSettings: build.query<
      PublicRecipesSettingsResponse,
      PublicRecipesSettingsResponseArgs
    >({
      query: params => ({
        url: `/app/recipes/public/settings`,
        params,
      }),
    }),
    togglePublicRecipesEditing: build.mutation<void, ToggleRecipeEditingModeResponse>({
      query: ({projectId, mode}) => ({
        url: `/app/recipes/public/settings/mode`,
        method: 'POST',
        params: {
          projectId,
          mode,
        },
      }),
    }),
    getPublicRecipesEditing: build.query<{isEnabled: boolean}, {projectId: ProjectId}>({
      query: ({projectId}) => ({
        url: `/app/recipes/public/settings/mode`,
        method: 'GET',
        params: {
          projectId,
        },
      }),
    }),
    uploadPrivateRecipe: build.mutation<void, UploadRecipeArgs>({
      query: ({file, fileName, projectId}) => {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('fileName', fileName)
        formData.append('projectId', projectId)

        return {
          url: `/app/recipes/private`,
          method: 'POST',
          body: formData,

          formData: true,
        }
      },
    }),
    updatePrivateRecipe: build.mutation<void, UpdateRecipeArgs>({
      query: ({recipeId, projectId, content}) => ({
        url: `/app/recipes/private`,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(content),
        params: {
          recipeId,
          projectId,
        },
      }),
    }),
    deletePrivateRecipe: build.mutation<void, DeletePrivateRecipeArgs>({
      query: ({recipeId, projectId}) => ({
        url: `/app/recipes/private`,
        method: 'DELETE',
        params: {
          recipeId,
          projectId,
        },
      }),
    }),
  }),
})
