import ArrowLeftIcon from '@jetbrains/icons/arrow-left'
import TrashIcon from '@jetbrains/icons/trash-12px.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import classNames from 'classnames'
import {useCallback, useRef, useState} from 'react'

import useIntersectionSelector from '../../../../hooks/useIntersectionSelector'
import type {ProjectId} from '../../../../types'
import RecipeListDeleteDialog from '../RecipeDeleteDialog/RecipeDeleteDialog'
import RecipeLabel from '../RecipeLabel/RecipeLabel'
import {useRecipesPermissions} from '../RecipesOverviewPage.context'
import {RecipeType, RecipeUsageType} from '../RecipesOverviewPage.rest'
import RecipeUsagesWrapper, {RecipeUsagesViewMode} from '../RecipeUsages/RecipeUsagesWrapper'

import RecipeViewCode from './RecipeView.code'
import {useRecipeViewData} from './RecipeView.hooks'

import styles from './RecipeView.module.css'

interface OwnProps {
  projectId: ProjectId
  recipeType: RecipeType
  recipeId: string
  onNavigateBack: () => void
}

function RecipeView({recipeId, recipeType, onNavigateBack, projectId}: OwnProps) {
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const {
    data: recipe,
    usages,
    isLoading,
    updateRecipe,
    error,
    resetError,
  } = useRecipeViewData({
    recipeId,
    recipeType,
    projectId,
  })

  const navigationRef = useRef<HTMLDivElement>(null)
  const [isPristine, setIsPristine] = useState(true)
  const [recipeContent, setRecipeContent] = useState<string>(recipe?.content || '')

  const {canEditProject, readOnlyUI} = useRecipesPermissions()

  const isStuck = useIntersectionSelector(
    navigationRef,
    entry => {
      const top = entry?.intersectionRect.top ?? 0
      return top != null && top <= 1
    },
    {
      threshold: 1,
      rootMargin: '-1px',
    },
  )

  const isScrolled = useIntersectionSelector(
    navigationRef,
    entry => {
      const top = entry?.boundingClientRect.top ?? 0
      return top != null && top < 0
    },
    {
      threshold: 1,
    },
  )

  const changeRecipeContent = useCallback(
    (content: string) => {
      resetError()
      setIsPristine(false)
      setRecipeContent(content)
    },
    [resetError],
  )

  const saveRecipe = useCallback(() => {
    updateRecipe(recipeContent)
  }, [recipeContent, updateRecipe])

  if (isLoading) {
    return <Loader />
  }

  return (
    <>
      <div
        className={classNames(styles.navigation, {[styles.stuck]: isStuck && !isScrolled})}
        ref={navigationRef}
      >
        <Button icon={ArrowLeftIcon} onClick={onNavigateBack} />
        <H3 className={styles.header}>{recipeId}</H3>
        <div className={styles.labels}>
          {recipe?.labels.map(label => (
            <RecipeLabel
              key={label.status}
              label={label}
              withTooltip={recipeType === RecipeType.PUBLIC_RECIPE}
            />
          ))}
        </div>
        {canEditProject && !readOnlyUI && (
          <>
            <ButtonSet className={styles.toolbar}>
              {(recipe?.editable && (
                <>
                  <Button disabled={isPristine} primary onClick={saveRecipe}>
                    {'Save'}
                  </Button>
                  <Button disabled={isPristine} onClick={() => window?.BS?.reload?.(true)}>
                    {'Cancel'}
                  </Button>
                </>
              )) ||
                null}

              <Button
                inline={false}
                onClick={() => setShowDeleteDialog(true)}
                icon={TrashIcon}
                title={'Delete recipe'}
              >
                {!recipe?.editable ? 'Delete recipe' : null}
              </Button>
            </ButtonSet>
          </>
        )}
      </div>
      <div className={styles.overview}>
        <div className={styles.entry}>
          <div className={styles.title}>{'Name'}</div>
          <div>{isLoading ? <LoaderInline /> : recipe?.title}</div>
        </div>
        <div className={styles.entry}>
          <div className={styles.title}>{'ID'}</div>
          <div>{isLoading ? <LoaderInline /> : `${recipe?.id}`}</div>
        </div>
        <div className={styles.entry}>
          <div className={styles.title}>{'Description'}</div>
          <div>{isLoading ? <LoaderInline /> : `${recipe?.description ?? '-'}`}</div>
        </div>
        <div className={styles.entry}>
          <div className={styles.title}>{'Type'}</div>
          <div>
            {isLoading ? (
              <LoaderInline />
            ) : recipe?.type === RecipeType.PRIVATE_RECIPE ? (
              'Private'
            ) : (
              'Public'
            )}
          </div>
        </div>
        <div className={styles.entry}>
          <div className={styles.title}>{'Usages'}</div>
          <div>
            {isLoading ? (
              <LoaderInline />
            ) : recipe?.usages.length === 0 ? (
              '-'
            ) : (
              <>
                <RecipeUsagesWrapper
                  usageType={RecipeUsageType.BUILD_TYPE}
                  usages={usages.buildConfigurations}
                  viewMode={RecipeUsagesViewMode.DROPDOWN}
                />
                <RecipeUsagesWrapper
                  usageType={RecipeUsageType.BUILD_TYPE_TEMPLATE}
                  usages={usages.buildTemplates}
                  viewMode={RecipeUsagesViewMode.DROPDOWN}
                />
                <RecipeUsagesWrapper
                  usageType={RecipeUsageType.PRIVATE_RECIPE}
                  usages={usages.privateRecipes}
                  viewMode={RecipeUsagesViewMode.DROPDOWN}
                />
              </>
            )}
          </div>
        </div>
      </div>
      <RecipeViewCode
        content={recipe?.content}
        editable={recipe?.editable}
        recipeType={recipeType}
        onContentChange={changeRecipeContent}
      />
      {error ? <div className={styles.error}>{error}</div> : null}
      {showDeleteDialog && recipe ? (
        <RecipeListDeleteDialog recipe={recipe} onClose={() => setShowDeleteDialog(false)} />
      ) : null}
    </>
  )
}

export default RecipeView
