import ChevronDownIcon from '@jetbrains/icons/chevron-down.svg'
import ChevronRightIcon from '@jetbrains/icons/chevron-right.svg'
import Dropdown, {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import classNames from 'classnames'
import plur from 'plur'
import {useMemo, useState} from 'react'

import type {RecipeUsageDto} from '../RecipesOverviewPage.rest'
import {RecipeUsageType} from '../RecipesOverviewPage.rest'

import RecipeUsagesList from './RecipeUsages.list'

import styles from './RecipeUsages.module.css'

export enum RecipeUsagesViewMode {
  DROPDOWN,
  COLLAPSING_LIST,
  PLAIN_LIST,
}

interface OwnProps {
  usages: Array<RecipeUsageDto>
  viewMode?: RecipeUsagesViewMode
  usageType?: RecipeUsageType
}

function RecipeUsagesWrapper({
  usages,
  viewMode = RecipeUsagesViewMode.COLLAPSING_LIST,
  usageType,
}: OwnProps) {
  const [showRecipeUsages, setShowRecipeUsages] = useState(false)
  const usagesText = useMemo(() => {
    let text = `Used in ${usages.length} `

    switch (usageType) {
      case RecipeUsageType.BUILD_TYPE:
        text += `build ${plur('configuration', usages.length)}`
        break
      case RecipeUsageType.BUILD_TYPE_TEMPLATE:
        text += `${plur('template', usages.length)}`
        break
      case RecipeUsageType.PRIVATE_RECIPE:
        text += `private ${plur('recipe', usages.length)}`
        break
      default:
        text += `${plur('entity', usages.length)}`
    }

    return text
  }, [usageType, usages.length])

  if (usages.length === 0) {
    return null
  }

  if (viewMode === RecipeUsagesViewMode.DROPDOWN) {
    return (
      <Dropdown
        className={styles.dropdown}
        hoverMode
        anchor={<Anchor className={classNames(styles.anchor)}>{usagesText}</Anchor>}
      >
        <Popup
          className={styles.popup}
          directions={[Directions.BOTTOM_CENTER, Directions.LEFT_BOTTOM, Directions.LEFT_TOP]}
        >
          <RecipeUsagesList usages={usages} />
        </Popup>
      </Dropdown>
    )
  }

  if (viewMode === RecipeUsagesViewMode.COLLAPSING_LIST) {
    return (
      <>
        <span
          role="presentation"
          className={styles.collapsible}
          onClick={() => setShowRecipeUsages(!showRecipeUsages)}
        >
          <Icon
            glyph={showRecipeUsages ? ChevronDownIcon : ChevronRightIcon}
            className={styles.chevron}
          />
          {usagesText}
        </span>
        <div className={classNames(showRecipeUsages && styles.expanded)}>
          {showRecipeUsages && <RecipeUsagesList usages={usages} />}
        </div>
      </>
    )
  }

  return <RecipeUsagesList usages={usages} />
}

export default RecipeUsagesWrapper
