import MoreIcon from '@jetbrains/icons/more-options-20px'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import DropdownMenu from '@jetbrains/ring-ui-built/components/dropdown-menu/dropdown-menu'
import {useMemo, useState} from 'react'

import {useSetHash} from '../../../../hooks/routes'
import type {ProjectId} from '../../../../types'
import RecipeListDeleteDialog from '../RecipeDeleteDialog/RecipeDeleteDialog'
import {generateRecipeHash} from '../RecipesOverview.utils'
import {useRecipesPermissions} from '../RecipesOverviewPage.context'
import type {RecipeDto} from '../RecipesOverviewPage.rest'

import styles from './RecipeList.module.css'

function RecipeListItemMore({item, projectId}: {item: RecipeDto; projectId: ProjectId}) {
  const setHash = useSetHash()
  const [showDeleteDialog, setShowDeleteDialog] = useState(false)
  const {canEditProject, readOnlyUI} = useRecipesPermissions()

  const dropDownItems = useMemo(() => {
    const result = [
      {
        rgItemType: DropdownMenu.ListProps.Type.LINK,
        label: 'View',
        className: styles.moreLink,
        onClick: () => setHash(generateRecipeHash(item.id.toString(), item.type, projectId)),
      },
    ]

    if (canEditProject && !readOnlyUI) {
      result.push({
        rgItemType: DropdownMenu.ListProps.Type.LINK,
        label: 'Delete',
        className: styles.moreLink,
        onClick: () => setShowDeleteDialog(true),
      })
    }

    return result
  }, [canEditProject, item.id, item.type, projectId, readOnlyUI, setHash])

  return (
    <>
      <span role="presentation" onClick={e => e.stopPropagation()}>
        <DropdownMenu data={dropDownItems} anchor={<Button icon={MoreIcon} />} />
      </span>
      {showDeleteDialog && (
        <RecipeListDeleteDialog recipe={item} onClose={() => setShowDeleteDialog(false)} />
      )}
    </>
  )
}

export default RecipeListItemMore
